const data = $input.first().json;
const esc = (v) => String(v ?? '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;');

const stats = data.stats || {};
const norm = stats.normalized_per_column || {};
const blank = stats.blank_per_column || {};
const columns = Array.isArray(data.columns) ? data.columns : [];
const sample = Array.isArray(data.sample) ? data.sample : [];
const sampleCols = ['start_datetime', 'end_datetime', 'language', 'interaction_id', 'contact'];

function kvTable(obj) {
  const keys = Object.keys(obj || {});
  if (!keys.length) return '<p><em>None</em></p>';
  const rows = keys.map((k) => `<tr><td>${esc(k)}</td><td>${esc(obj[k])}</td></tr>`).join('');
  return `<table><thead><tr><th>Column</th><th>Count</th></tr></thead><tbody>${rows}</tbody></table>`;
}

function columnsTable() {
  if (!columns.length) return '<p><em>No columns</em></p>';
  const rows = columns.map((c) => `<tr><td>${esc(c.name)}</td><td>${esc(c.datatype)}</td></tr>`).join('');
  return `<table><thead><tr><th>Name</th><th>Datatype</th></tr></thead><tbody>${rows}</tbody></table>`;
}

function sampleTable() {
  if (!sample.length) return '<p><em>No sample rows</em></p>';
  const head = sampleCols.map((c) => `<th>${esc(c)}</th>`).join('');
  const rows = sample.map((row) => `<tr>${sampleCols.map((c) => `<td>${esc(row[c])}</td>`).join('')}</tr>`).join('');
  return `<table><thead><tr>${head}</tr></thead><tbody>${rows}</tbody></table>`;
}

const decideUrl = `http://localhost:5678/form/csv-decide?upload_id=${encodeURIComponent(data.upload_id || '')}`;

const html = `
<h2>Upload received</h2>
<p><strong>Upload ID:</strong> ${esc(data.upload_id)}<br>
<strong>Sections:</strong> ${esc(data.section_count)} (max ${esc(data.section_max_rows)} rows each)</p>

<h3>Cleaning stats</h3>
<table>
  <thead><tr><th>Metric</th><th>Value</th></tr></thead>
  <tbody>
    <tr><td>rows_in</td><td>${esc(stats.rows_in ?? 0)}</td></tr>
    <tr><td>rows_out</td><td>${esc(stats.rows_out ?? 0)}</td></tr>
    <tr><td>rows_error</td><td>${esc(stats.rows_error ?? 0)}</td></tr>
  </tbody>
</table>

<h3>Normalized per column</h3>
${kvTable(norm)}

<h3>Blank per column</h3>
${kvTable(blank)}

<h3>Columns</h3>
${columnsTable()}

<h3>Sample (${esc(sample.length)} staging rows)</h3>
${sampleTable()}

<hr>
<p><a href="${esc(decideUrl)}"><strong>Continue to Approve / Deny →</strong></a></p>
`.trim();

return [{ json: { html, upload_id: data.upload_id, decide_url: decideUrl } }];
